package com.loja.checkout.dominio;

import com.loja.checkout.comum.Dinheiro;
import com.loja.checkout.dominio.clube.NivelClube;
import com.loja.checkout.dominio.cupom.Cupom;
import com.loja.checkout.dominio.entrega.ModalidadeEntrega;
import com.loja.checkout.dominio.pagamento.FormaPagamento;

import java.math.BigDecimal;
import java.util.List;

/** Pedido ja validado, pronto para o calculo do resumo. */
public record Pedido(List<ItemPedido> itens,
                     ModalidadeEntrega modalidadeEntrega,
                     Cupom cupom,
                     FormaPagamento formaPagamento,
                     int parcelas,
                     NivelClube nivelClube,
                     Regiao regiao) {

    /** Soma dos produtos (preco x quantidade de cada item). */
    public BigDecimal subtotalProdutos() {
        return Dinheiro.valor(itens.stream()
                .map(ItemPedido::total)
                .reduce(BigDecimal.ZERO, BigDecimal::add));
    }

    /** Peso total do pedido em kg, sem arredondar. */
    public BigDecimal pesoTotalKg() {
        return itens.stream()
                .map(ItemPedido::peso)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
EOF
